local StoreChargeReward = Class('StoreChargeReward')
local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
local WelfareConstants = import("Game.UI.Welfare.WelfareConstants")
local CellPath = "Game.UI.ResidentEvent.StoreChargeRewardNode"
local ItemCell = "Cell"
function StoreChargeReward:__init()
    self.allVos = nil
end

function StoreChargeReward:__delete()
    self.allVos = nil
end

function StoreChargeReward:Awake()
    self:AddUIClick()
    self:InitData()
    KTool.SetActive(self.BtnRoleNameNode.gameObject,false)
    KTool.SetActive(self.BtnRoleGoods.gameObject,false)
    if self.BtnRoleNameNode then
        local env = CfUtils.GetLuaScr(self.BtnRoleNameNode,"Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            self.btnRoleNameEnv = env
        end
    end
end

function StoreChargeReward:InitData()
    self.allVos = CfUtils.GetCf(AutoIds.IdSetting1801,"CumulativeRecharge",true)
    table.sort(self.allVos,function(a,b) return a.amount < b.amount  end)
end

function StoreChargeReward:AddUIClick()
    SetButtonAction(self.BtnExplain,Bind(self,self.OnBtnExplainClick))
    SetButtonAction(self.BtnCost,Bind(self,self.OnBtnCostClick))
    SetButtonAction(self.BtnOneKeyGet,Bind(self,self.OnBtnOneKeyGetClick))
    SetButtonAction(self.BtnRoleGoods,Bind(self,self.OnBtnGoodsClick))
end

function StoreChargeReward:Refresh(data,index)
    if isNull(data) then return end
    self.data = data
    self.curIndex = index
    GameUtils.Request(Interfaces.PlayerPayCumulative, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        local listRewardIds = checkTable(jsonData.payCumulative)
        self.getRewardIds = listRewardIds
        if jsonData.payCumulativeNum then
            -- 改为服务器端返回
            if not IsNull(playerComp) then
                local playDJ = playerComp.playerDojo
                if not IsNull(playDJ) then
                    playDJ.payCumulative = checkInt(jsonData.payCumulativeNum)
                end
            end
            self.curPoint = checkInt(jsonData.payCumulativeNum)
        end
        self:RefreshDialog()
    end)
    self:RefreshStaticShow()
end

function StoreChargeReward:RefreshDialog()
    self:RefreshGoodsShow()
    self:RefreshList()
end

function StoreChargeReward:RefreshList()
    local index = self:GetCurIndexByPoint()
    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#self.allVos, Bind(self, self.OnRefreshCellIndex))
            self.ScrollView:MovePanelToItemIndex(index - 1)
        else
            GameUtils.ReloadData(self.ScrollView, #self.allVos)
            self.ScrollView:MovePanelToItemIndex(index - 1)
        end
    end
end

function StoreChargeReward:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.allVos then
        return
    end
    local cell = listView:NewListViewItem(ItemCell)
    local tableCellEnv = CfUtils.GetLuaScr(cell, CellPath)
    tableCellEnv:SetCallBackAndIndex(Bind(self,self.OnDrawRewardClick),index + 1,self)
    tableCellEnv:RefreshShow(self.allVos[index + 1])
    return cell
end

function StoreChargeReward:OnDrawRewardClick(data)
    local point = self.curPoint
    if point >= data.amount then
        local isGet = self:IsGetById(data.id)
        if not isGet then
            self:DrawReward(data)
        end
    end
end

function StoreChargeReward:DrawReward(data)
    local id
    if not isNull(data) then
        id = data.id
    end
    GameUtils.Request(Interfaces.PlayerDrawPayCumulative, { rewardId = id }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        local rewards = checkTable(jsonData.rewards)
        --- 奖励领取
        if table.count(rewards) > 0 then
            GoodsUtils.DrawRewards(rewards, true)
            CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        end
        self:SetData(id) -- 列表更新 && 界面刷新

        local isHave = self:IsHaveRewardToGet()
        GameUtils.UpdateServerRedPointData({unAccumulativePay = isHave and 0 or -1})

        self:RefreshList()
        self:RefreshDesc()
    end)
end

function StoreChargeReward:IsHaveRewardToGet()
    for i, v in pairs(self.allVos) do
        if self.curPoint >= v.amount then
            local isGet = self:IsGetById(v.id)
            if not isGet then
                return true
            end
        end
    end
    return false
end

function StoreChargeReward:SetData(id)
    if id then
        if not self:IsGetById(id) then
            table.insert(self.getRewardIds, id)
        end
    else
        for i, v in pairs(self.allVos) do
            if self.curPoint >= v.amount and not self:IsGetById(v.id) then
                table.insert(self.getRewardIds,v.id)
            end
        end
    end
end

---是否领取了当前档位奖励
function StoreChargeReward:IsGetById(id)
    for i, v in pairs(self.getRewardIds) do
        if v == id  then
            return true
        end
    end
    return false
end

function StoreChargeReward:GetCurVoByPoint(point)
    local curPoint = point or self.curPoint
    for i, v in pairs(self.allVos) do
        if curPoint < v.amount then
            return v
        end
    end
    return self.allVos[#self.allVos]
end

function StoreChargeReward:GetCurIndexByPoint(point)
    local curPoint = point or self.curPoint
    local isFind = false
    for i, v in pairs(self.allVos) do
        local isGet = self:IsGetById(v.id)
        if curPoint >= v.amount and not isGet then
            isFind = true
            return v.id
        end
    end

    if not isFind then
        for i, v in pairs(self.allVos) do
            local isGet = self:IsGetById(v.id)
            if  not isGet then
                return v.id
            end
        end
    end
    return 1
end

---刷新充值数量
function StoreChargeReward:RefreshGoodsShow()
    CfUtils.FillText(self.GoodNum, self.curPoint)
    local goodsId = self.data.costType
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if goodsVo then
        CfUtils.FillImage(self.ImgGoodIcon,goodsVo.photoPath)
    end
    local vo = self:GetCurVoByPoint()
    if vo then
        self.Slider.value = self.curPoint/vo.amount
        CfUtils.FillText(self.SliderNum,table.concat({self.curPoint,"/",vo.amount}))
        self:RefreshDesc(vo)
    end
end

function StoreChargeReward:RefreshDesc(vo)
    if isNull(vo) then
        vo = self:GetCurVoByPoint()
    end
    if self:IsToMaxLevel() then
        if self:IsGetAllReward() then
            CfUtils.FillText(self.TextDesc,localize("所有阶段奖励已领取完毕"))
        else
            CfUtils.FillText(self.TextDesc,localize("所有阶段奖励已可领取"))
        end
    else
        local desc = localize("还需获得_num_充值积分即可领取奖励",{_num_ = string.format("<color=#e71f55>%s</color>",vo.amount - self.curPoint)})
        CfUtils.FillText(self.TextDesc,desc)
    end
end

