---武装展示
function StoreChargeReward:SetRoleInfo()
    local cardId = self.allVos[1].showCard
    local rate = self.allVos[1].rare
    if isNull(cardId) or isNull(rate) then return end
    local roleData = CardConfMgr:GetInstance():GetCardByRefId(cardId)   
    print("->ContinuousRechargeDialog:SetRoleInfo", cardId, table.dump(checkTable(roleData)))
    if isNull(roleData) then return end
    if IsNull(self.BtnRoleNameNode) then return end

    KTool.SetActive(self.BtnRoleNameNode, true)
    ---@type CommonBtnRoleNameNode
    local _ltNode = self.btnRoleNameEnv
    _ltNode:RefreshSelf(cardId, rate,function()
        xTry(function()
            local GachaponUtils = import('Game.Gachapon.GachaponUtils')
            -- CfUtils.CookieSave("UIWelfareMainDialog_Index",self.curIndex)
            GachaponUtils.OpenDetail(cardId, {{ id = Constants.UITypeIds.UIWelfareMainDialog}})
        end)
    end, false)
    local cardNode =  self.RoleItem.transform:Find("cardNode")
    if isNull(cardNode) then
        local prefabPath =  string.fmt("Prefabs/ResidentEvent/StoreChargeRewardRole_num_.prefab", {_num_ = cardId })
        local  go = GameUtils.LoadBundleAsync(prefabPath, self.RoleItem.gameObject, false)
        go.name = "cardNode" 
    end
end

---是否到达最大等级 积分超过了上限
function StoreChargeReward:IsToMaxLevel()
    return self.curPoint > self.allVos[#self.allVos].amount
end
---是否领取了所有的奖励
function StoreChargeReward:IsGetAllReward()
    return table.count(self.getRewardIds) == table.count(self.allVos)
end

